<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'; import Notice from '@/components/Notice.vue'; import StatusPanel from '@/components/StatusPanel.vue'; import { useDashboardStore } from '@/stores/dashboard'
const store = useDashboardStore(); const live = ref(false); let stream: EventSource | null = null; let retry: number | null = null
function connect() { stream?.close(); stream = new EventSource('/api/v1/events'); stream.onopen = () => { live.value = true; void store.loadPublic() }; ['connected', 'status-changed', 'device-changed'].forEach((name) => stream?.addEventListener(name, () => void store.loadPublic())); stream.onerror = () => { live.value = false; stream?.close(); retry = window.setTimeout(connect, 3000) } }
onMounted(async () => { await store.loadPublic(); connect() }); onBeforeUnmount(() => { stream?.close(); if (retry) clearTimeout(retry) })
</script>
<template><div class="page"><div class="page-heading"><div><span class="eyebrow">公开面板</span><h1>现在的状态</h1></div><span class="live" :class="{ online: live }"><i/>{{ live ? '实时连接' : '正在重连' }}</span></div><Notice :message="store.error" type="error"/><p v-if="store.loading && !store.snapshot" class="empty">正在获取服务器快照…</p><template v-else-if="store.snapshot"><StatusPanel :snapshot="store.snapshot" :presets="store.presets"/><section class="section"><div class="section-title"><h2>设备</h2><span>{{ store.snapshot.devices.length }} 台</span></div><p v-if="store.snapshot.private" class="empty">设备信息已由隐私模式隐藏。</p><p v-else-if="!store.snapshot.devices.length" class="empty">还没有设备上报状态。</p><div v-else class="device-grid"><article v-for="device in store.snapshot.devices" :key="device.id" class="device-card"><div class="device-icon">{{ device.using ? '●' : '○' }}</div><div><h3>{{ device.name }}</h3><p>{{ device.status || '暂无活动信息' }}</p><small>{{ new Date(device.last_updated * 1000).toLocaleString() }}</small></div></article></div></section></template></div></template>
